scripts.factorial_mod:
def solve(inputs: dict) -> float:
    n = inputs['N']
    mod = inputs['MOD']

    # Calculate n! mod MOD
    result = 1
    for i in range(1, n + 1):
        result = (result * i) % mod

    return float(result)

scripts.iterative_mod:
def solve(inputs: dict) -> float:
    x = inputs['X']
    c = inputs['C']
    mod = inputs['MOD']
    k = inputs['K']

    # Repeat k times
    for _ in range(k):
        x = (x * x + c) % mod

    return float(x)

scripts.continued_fraction:
def solve(inputs: dict) -> float:
    terms = inputs['TERMS']

    # p_{-1} = 1, p_0 = a_0
    p_prev2 = 1
    p_prev1 = terms[0]

    # Compute p_i for i = 1 to len(terms)-1
    for i in range(1, len(terms)):
        p_curr = terms[i] * p_prev1 + p_prev2
        p_prev2 = p_prev1
        p_prev1 = p_curr

    # The final numerator is p_{len(terms)-1}
    return float(p_prev1)

